sp_widget.client_script:
api.controller = function() {
  var c = this; c.open = 0;
  c.toggle = function(i) { c.open = (c.open === i) ? -1 : i; };
};

sp_widget.css:
.cp-help { max-width:760px; margin:0 auto; padding:32px 28px; }
.cp-acc { margin-top:18px; }
.cp-acc__item { background:#fff; border:1px solid var(--cp-line); border-radius:12px; margin-bottom:10px; overflow:hidden; transition:.18s; }
.cp-acc__item.is-open { border-color:rgba(197,160,101,.55); box-shadow:var(--cp-card-shadow); }
.cp-acc__q { width:100%; display:flex; justify-content:space-between; align-items:center; gap:12px;
  padding:16px 18px; background:none; border:none; cursor:pointer; text-align:left;
  font-size:15px; font-weight:750; color:var(--cp-navy); font-family:var(--cp-font); }
.cp-acc__chev { color:var(--cp-gold); font-size:20px; font-weight:700; transition:.2s; }
.cp-acc__item.is-open .cp-acc__chev { transform:rotate(45deg); }
.cp-acc__a { padding:0 18px 18px; color:var(--cp-muted); font-size:14px; line-height:1.6; }

sp_widget.script:
(function() {
  data.faqs = [
    { q:'What documents should I upload?',
      a:'Anything that supports your claim — photos of the damage, receipts, invoices, medical or police reports, proof of ownership. Clear PDFs or images work best.' },
    { q:'How long does review take?',
      a:'Standard claims target resolution within 48 hours; critical claims within 4 hours. High-value claims need manager and finance approval, which can add time.' },
    { q:'What does each claim state mean?',
      a:'New: received. Under Review: an agent is assessing it. Investigation: extra checks such as fraud review. Approved/Rejected: a decision was made. Closed: fully resolved.' },
    { q:'What happens if documents are missing?',
      a:'Your claim shows a "Documents needed" notice and you get a notification. Upload the requested files and reply in the claim Activity.' },
    { q:'Who can see my claim?',
      a:'Only you and the assigned claim team. Other customers cannot see your claims.' }
  ];
})();
